/* WORKSPACE_EDITOR_START */
/* WORKSPACE_CORE_START */
const WorkspaceCore={
 components:{tl:'画板入口',shelf:'模型货架',gb:'助手与工具',tools:'画板工具栏'},
 appearance(patch){const out={},ranges={fontSize:[12,18],opacity:[.55,1],blur:[0,28],radius:[6,24],stroke:[1,3]};for(const[k,v]of Object.entries(patch||{})){if(k==='paperColor'||k==='gridColor'){if(!/^#[0-9a-f]{6}$/i.test(String(v)))throw new Error('颜色需为 #RRGGBB');out[k]=String(v)}else if(k==='gridVisible'){if(typeof v!=='boolean')throw new Error('网格开关需为布尔值');out[k]=v}else if(ranges[k]){const n=Number(v),[min,max]=ranges[k];if(!Number.isFinite(n)||n<min||n>max)throw new Error('样式数值超出范围：'+k);out[k]=n}else throw new Error('不支持的样式字段：'+k)}return out},
 layout(previous,componentId,patch,vw,vh){if(!Object.hasOwn(this.components,componentId))throw new Error('请选择可编辑组件');const out={...(previous||{})};for(const[k,v]of Object.entries(patch)){if(k==='visible'){if(typeof v!=='boolean')throw new Error('组件显示开关需为布尔值');out.visible=v}else if(['x','y','width'].includes(k)){const n=Number(v);if(!Number.isFinite(n))throw new Error('布局请使用数字');out[k]=k==='width'?Math.max(160,Math.min(vw-16,n)):Math.max(8,Math.min((k==='x'?vw:vh)-40,n))}else throw new Error('不支持的布局字段：'+k)}return out},
 patch(previous,appearance){return{...(previous||{}),appearance:{...(previous?.appearance||{}),...this.appearance(appearance)},layout:{...(previous?.layout||{})}}}
};
/* WORKSPACE_CORE_END */
const WE={editing:false,drag:null,before:null};
const workspaceConfig=()=>B()?.interface||{appearance:{},layout:{}};
CAT.push(['workspace.open','打开界面编辑：布局、组件、样式可手动调整',''],['workspace.appearance','只修改点名的界面样式，保留手动布局','paperColor?,gridColor?,gridVisible?,fontSize?,opacity?,blur?,radius?,stroke?'],['workspace.layout','只调整指定组件的位置、宽度或可见性','componentId,x?,y?,width?,visible?'],['workspace.reset','恢复本画板默认界面，可撤销','componentId?']);
ACT['workspace.open']=()=>{openPan('workspace');return'已打开界面编辑，修改只属于当前画板'};
ACT['workspace.appearance']=a=>{const patch=WorkspaceCore.appearance(a);pushUndo();B().interface=WorkspaceCore.patch(B().interface,patch);save();workspaceApply();return'已修改点名样式，手动布局保留，可撤销'};
ACT['workspace.layout']=a=>{const {componentId,...patch}=a,cfg=workspaceConfig(),layout=WorkspaceCore.layout(cfg.layout?.[componentId],componentId,patch,innerWidth,innerHeight);pushUndo();B().interface={...cfg,layout:{...cfg.layout,[componentId]:layout}};save();workspaceApply();return'已调整 '+WorkspaceCore.components[componentId]+'，其他组件保持原位，可撤销'};
ACT['workspace.reset']=a=>{if(a.componentId&&!Object.hasOwn(WorkspaceCore.components,a.componentId))throw'组件不存在';pushUndo();if(a.componentId){const cfg=workspaceConfig();delete cfg.layout[a.componentId];B().interface=cfg}else delete B().interface;save();workspaceApply();return'已恢复默认界面，可撤销'};
function workspaceApply(){const cfg=workspaceConfig(),a=cfg.appearance||{},body=document.body;body.classList.toggle('workspace-custom',Object.keys(a).length>0);body.classList.toggle('workspace-editing',WE.editing);const props={'--paper':a.paperColor,'--workspace-font':a.fontSize?a.fontSize+'px':null,'--workspace-radius':a.radius?a.radius+'px':null,'--workspace-stroke':a.stroke?a.stroke+'px':null,'--clarity-glass':a.opacity!==undefined?'rgba(250,251,253,'+a.opacity+')':null,'--clarity-blur':a.blur!==undefined?'saturate(150%) blur('+a.blur+'px)':null};for(const[k,v]of Object.entries(props)){if(v!==null&&v!==undefined)body.style.setProperty(k,v);else body.style.removeProperty(k)}
 for(const[id,label]of Object.entries(WorkspaceCore.components)){const el=document.getElementById(id);if(!el)continue;const box=cfg.layout?.[id];el.hidden=box?.visible===false;if(WE.drag?.element===el)continue;if(el.dataset.workspaceApplied){for(const p of ['left','right','top','bottom','transform','width'])el.style[p]='';delete el.dataset.workspaceApplied}if(box&&(box.x!==undefined||box.y!==undefined||box.width!==undefined)){const r=el.getBoundingClientRect(),width=Math.min(box.width||r.width,innerWidth-16),x=Math.max(8,Math.min(innerWidth-width-8,box.x??r.x)),y=Math.max(8,Math.min(innerHeight-r.height-8,box.y??r.y));Object.assign(el.style,{left:x+'px',top:y+'px',right:'auto',bottom:'auto',transform:'none',...(box.width?{width:width+'px'}:{})});el.dataset.workspaceApplied='1'}el.querySelectorAll('[data-workspace-move],[data-workspace-size]').forEach(e=>e.remove());if(WE.editing&&!el.hidden){el.insertAdjacentHTML('beforeend',`<button class="workspace-grip" data-workspace-move="${id}" aria-label="移动${label}">${icon('grip',13)}</button><button class="workspace-size" data-workspace-size="${id}" aria-label="调整${label}宽度">↔</button>`)}}
 const recover=$('#workspace-recover');if(recover)recover.hidden=!['tl','tools','gb'].every(id=>cfg.layout?.[id]?.visible===false);
 workspaceViewBase(0);workspaceGrid();
}
function workspaceGrid(){const a=workspaceConfig().appearance||{},el=$('#bd');if(a.gridVisible===false)el.style.backgroundImage='none';else if(a.gridColor){el.style.backgroundImage=`linear-gradient(to right,${a.gridColor} 1px,transparent 1px),linear-gradient(to bottom,${a.gridColor} 1px,transparent 1px)`}}
const workspaceViewBase=applyView;applyView=function(an){workspaceViewBase(an);workspaceGrid()};
const workspaceTopBase=renderTop;renderTop=function(){workspaceTopBase();$('#tools').insertAdjacentHTML('beforeend',`<button data-act="workspace.open" aria-label="编辑界面" title="编辑界面">${icon('palette',16)}<span class="memphis-label">编辑界面</span></button>`);workspaceApply()};
function workspaceMarkup(){const a=workspaceConfig().appearance||{},layout=workspaceConfig().layout||{};const range=(key,label,min,max,step,value)=>`<label class="workspace-field">${label}<input type="range" data-workspace-style="${key}" min="${min}" max="${max}" step="${step}" value="${a[key]??value}"><output>${a[key]??value}</output></label>`;return `<h3>${icon('palette',17)}编辑界面<button class="x" data-close="pan" aria-label="关闭">${icon('close')}</button></h3><p class="lab">这是你的工作空间。手动与AI使用同一套操作，只改变点名的部分；每张画板独立保存。</p><button data-workspace-drag-mode aria-pressed="${WE.editing}">${WE.editing?'结束手动布局':'开始手动布局'}</button><p class="lab">开启后拖各栏的小把手移动，右侧手柄调整宽度。</p><details open><summary>样式</summary><label class="workspace-field">画板底色<input data-workspace-style="paperColor" value="${esc(a.paperColor||'#F5F7FA')}" aria-label="画板底色"></label><label class="workspace-field">网格颜色<input data-workspace-style="gridColor" value="${esc(a.gridColor||'#D5DBE3')}" aria-label="网格颜色"></label><label class="row"><input type="checkbox" data-workspace-style="gridVisible" ${a.gridVisible!==false?'checked':''}>显示网格</label><label class="workspace-field">界面字号<select data-workspace-style="fontSize" aria-label="界面字号">${[12,14,16,18].map(n=>`<option value="${n}" ${(a.fontSize||14)===n?'selected':''}>${n}px</option>`).join('')}</select></label>${range('opacity','工具栏透明度',.55,1,.01,.74)}${range('blur','毛玻璃模糊',0,28,1,16)}${range('radius','组件圆角',6,24,1,14)}${range('stroke','组件描边',1,3,.5,1.5)}</details><details><summary>组件显示与布局</summary>${Object.entries(WorkspaceCore.components).map(([id,name])=>`<div class="row"><label><input type="checkbox" data-workspace-visible="${id}" ${layout[id]?.visible!==false?'checked':''}>${name}</label><button data-workspace-reset="${id}" aria-label="恢复${name}布局">恢复位置</button></div>`).join('')}</details><div class="row">${B_('undo',{},'撤销','undo')}${B_('redo',{},'重做','redo')}${B_('workspace.reset',{},'恢复本画板默认')}</div><p class="lab">例如可以告诉助手：“只把工具栏模糊调低一点，保留我摆的位置。”</p>`}
const workspacePanBase=renderPan;renderPan=function(){if(panK==='workspace'){$('#pan').classList.remove('cl-boards');$('#pan').classList.add('workspace-panel');$('#pan').innerHTML=workspaceMarkup();dmDecorate()}else{$('#pan').classList.remove('workspace-panel');workspacePanBase();if(panK==='boards'&&!$('#pan [data-act="workspace.open"]'))$('#pan .cl-board-footer')?.insertAdjacentHTML('beforeend',B_('workspace.open',{},'编辑界面','palette'))}};
const workspaceAllBase=renderAll;renderAll=function(){workspaceAllBase();workspaceApply()};
const workspaceRestoreBase=restore;restore=function(str){workspaceRestoreBase(str);workspaceApply()};
const recovery=document.createElement('button');recovery.id='workspace-recover';recovery.hidden=true;recovery.dataset.act='workspace.open';recovery.innerHTML=icon('palette',16)+'编辑界面';document.body.append(recovery);
function workspaceInputValue(t){if(t.type==='checkbox')return t.checked;if(t.type==='range'||t.tagName==='SELECT')return Number(t.value);return t.value}
document.addEventListener('pointerdown',e=>{const t=e.target;if(t.matches('[data-workspace-style]'))WE.before=snap();const el=t.closest('[data-workspace-move],[data-workspace-size]');if(!el||e.button!==0)return;e.preventDefault();e.stopImmediatePropagation();const id=el.dataset.workspaceMove||el.dataset.workspaceSize,target=document.getElementById(id),r=target.getBoundingClientRect();WE.drag={id,element:target,sizing:!!el.dataset.workspaceSize,sx:e.clientX,sy:e.clientY,x:r.x,y:r.y,w:r.width,h:r.height,before:snap()};},true);
document.addEventListener('focusin',e=>{if(e.target.matches('[data-workspace-style]')&&!WE.before)WE.before=snap()});
document.addEventListener('input',e=>{const t=e.target;if(!t.dataset.workspaceStyle)return;if(!WE.before)WE.before=snap();try{const patch=WorkspaceCore.appearance({[t.dataset.workspaceStyle]:workspaceInputValue(t)});B().interface=WorkspaceCore.patch(B().interface,patch);t.setCustomValidity('');workspaceApply();if(t.nextElementSibling?.tagName==='OUTPUT')t.nextElementSibling.value=t.value}catch(error){t.setCustomValidity(error.message)}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.workspaceStyle){if(!t.checkValidity())return;const before=WE.before;WE.before=null;if(before&&before!==snap())pushUndo(before);save();workspaceApply()}if(t.dataset.workspaceVisible)act('workspace.layout',{componentId:t.dataset.workspaceVisible,visible:t.checked})});
document.addEventListener('pointermove',e=>{const d=WE.drag;if(!d)return;e.preventDefault();if(d.sizing){d.width=Math.max(160,Math.min(innerWidth-16,d.w+e.clientX-d.sx));d.element.style.width=d.width+'px'}else{d.nextX=Math.max(8,Math.min(innerWidth-d.w-8,d.x+e.clientX-d.sx));d.nextY=Math.max(8,Math.min(innerHeight-d.h-8,d.y+e.clientY-d.sy));Object.assign(d.element.style,{left:d.nextX+'px',top:d.nextY+'px',right:'auto',bottom:'auto',transform:'none'})}},true);
document.addEventListener('pointerup',e=>{const d=WE.drag;if(!d)return;WE.drag=null;e.stopImmediatePropagation();const cfg=workspaceConfig(),patch=d.sizing?{width:d.width||d.w}:{x:d.nextX??d.x,y:d.nextY??d.y};pushUndo(d.before);B().interface={...cfg,layout:{...cfg.layout,[d.id]:WorkspaceCore.layout(cfg.layout?.[d.id],d.id,patch,innerWidth,innerHeight)}};save();workspaceApply()},true);
document.addEventListener('pointercancel',()=>{const d=WE.drag;if(!d)return;WE.drag=null;restore(d.before)},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-workspace-drag-mode')){WE.editing=!WE.editing;workspaceApply();renderPan()}else if(b.dataset.workspaceReset)act('workspace.reset',{componentId:b.dataset.workspaceReset})},true);
const workspaceContextBase=asContext;asContext=function(){return{...workspaceContextBase(),workspace:{boardId:state.activeBoard,appearance:workspaceConfig().appearance||{},layout:Object.entries(workspaceConfig().layout||{}).map(([componentId,box])=>({componentId,...box}))}}};
addEventListener('resize',workspaceApply);
workspaceApply();
/* WORKSPACE_EDITOR_END */
